    impl ::std::convert::From<super::TraceContext> for TraceContext {
        fn from(value: super::TraceContext) -> Self {
            Self {
                parent_span_id: Ok(value.parent_span_id),
                span_id: Ok(value.span_id),
                trace_id: Ok(value.trace_id),
            }
        }
    }
